using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Drawing.Text;
using System.IO;
using System.Linq;
using System.Media;
using System.Reflection;

namespace PlutoArena
{
    /// <summary>
    /// The 2.0 look: window backgrounds and button sprites embedded in the exe
    /// (folder Skin, generated by tools/make_skin.py - original art), plus the
    /// colors and fonts used for the text the program draws itself.
    /// </summary>
    internal static class Skin
    {
        /// <summary>Transparent border around every button sprite (glow and shadow).</summary>
        public const int Margin = 5;

        /// <summary>Transparent border around the switch sprites.</summary>
        public const int SwitchMargin = 3;

        public static readonly Color Phosphor = Color.FromArgb(125, 255, 150);
        public static readonly Color PhosphorDim = Color.FromArgb(55, 140, 80);
        public static readonly Color Amber = Color.FromArgb(255, 190, 70);

        private static readonly Dictionary<string, Bitmap?> images = new(StringComparer.OrdinalIgnoreCase);
        private static string? monoFamily;

        /// <summary>Accent color of a race (window details, PLAY, glows).</summary>
        public static Color Accent(string race) => race.ToLowerInvariant() switch
        {
            "terran" => Color.FromArgb(80, 165, 255),
            "protoss" => Color.FromArgb(255, 196, 70),
            "zerg" => Color.FromArgb(185, 85, 255),
            _ => Color.FromArgb(200, 205, 215)
        };

        public static string Key(string race) => race.ToLowerInvariant() switch
        {
            "terran" => "terran",
            "protoss" => "protoss",
            "zerg" => "zerg",
            _ => "random"
        };

        public static string MonoFamily => monoFamily ??= Theme.Pick("Consolas", "Lucida Console", "Courier New");

        public static Font Mono(float size, FontStyle style = FontStyle.Regular) =>
            new Font(MonoFamily, size, style, GraphicsUnit.Point);

        /// <summary>An embedded file of the Skin folder, or null.</summary>
        public static Stream? Open(string file)
        {
            try
            {
                Assembly asm = typeof(Skin).Assembly;
                string? name = asm.GetManifestResourceNames()
                    .FirstOrDefault(n => n.EndsWith(".Skin." + file, StringComparison.OrdinalIgnoreCase));

                return name == null ? null : asm.GetManifestResourceStream(name);
            }
            catch
            {
                return null;
            }
        }

        /// <summary>Sprite or background by name (without extension), or null if missing.</summary>
        public static Bitmap? Get(string name)
        {
            if (images.TryGetValue(name, out Bitmap? cached))
                return cached;

            Bitmap? bmp = null;

            foreach (string ext in new[] { ".png", ".jpg" })
            {
                using Stream? s = Open(name + ext);

                if (s == null)
                    continue;

                try
                {
                    using Bitmap raw = new Bitmap(s);

                    // Premultiplied copy: draws much faster, and the stream can be closed.
                    bmp = new Bitmap(raw.Width, raw.Height, PixelFormat.Format32bppPArgb);
                    using Graphics g = Graphics.FromImage(bmp);
                    g.CompositingMode = CompositingMode.SourceCopy;
                    g.InterpolationMode = InterpolationMode.NearestNeighbor;
                    g.PixelOffsetMode = PixelOffsetMode.Half;
                    g.DrawImage(raw, new Rectangle(0, 0, raw.Width, raw.Height));
                }
                catch
                {
                    bmp = null;
                }

                break;
            }

            images[name] = bmp;
            return bmp;
        }

        /// <summary>Draws a sprite 1:1 (no smoothing, no DPI scaling).</summary>
        public static void Blit(Graphics g, Bitmap bmp, int x, int y, ImageAttributes? attributes = null)
        {
            GraphicsState state = g.Save();
            g.InterpolationMode = InterpolationMode.NearestNeighbor;
            g.PixelOffsetMode = PixelOffsetMode.Half;
            g.CompositingQuality = CompositingQuality.HighSpeed;

            Rectangle dest = new Rectangle(x, y, bmp.Width, bmp.Height);

            if (attributes == null)
                g.DrawImage(bmp, dest);
            else
                g.DrawImage(bmp, dest, 0, 0, bmp.Width, bmp.Height, GraphicsUnit.Pixel, attributes);

            g.Restore(state);
        }

        /// <summary>Darker, less saturated drawing for disabled controls without their own sprite.</summary>
        public static ImageAttributes Dimmed()
        {
            const float k = 0.45f, s = 0.12f;
            ImageAttributes a = new ImageAttributes();
            a.SetColorMatrix(new ColorMatrix(new[]
            {
                new[] { k + s, s, s, 0f, 0f },
                new[] { s, k + s, s, 0f, 0f },
                new[] { s, s, k + s, 0f, 0f },
                new[] { 0f, 0f, 0f, 1f, 0f },
                new[] { 0f, 0f, 0f, 0f, 1f }
            }));
            return a;
        }

        /// <summary>
        /// A green monitor panel drawn in code (dialogs): dark glass, scan
        /// lines, inner shadow and a thin metal rim.
        /// </summary>
        public static void DrawCrt(Graphics g, RectangleF r, float chamfer = 8)
        {
            using GraphicsPath shape = Theme.Chamfer(r, chamfer);

            using (LinearGradientBrush fill = new LinearGradientBrush(r, Color.FromArgb(14, 36, 22), Color.FromArgb(7, 18, 11), 90f))
                g.FillPath(fill, shape);

            GraphicsState state = g.Save();
            g.SetClip(shape);

            // Phosphor bloom in the middle
            using (GraphicsPath bloom = new GraphicsPath())
            {
                bloom.AddEllipse(r.X + r.Width * 0.1f, r.Y + r.Height * 0.05f, r.Width * 0.8f, r.Height * 0.9f);
                using PathGradientBrush b = new PathGradientBrush(bloom)
                {
                    CenterColor = Color.FromArgb(34, 60, 160, 90),
                    SurroundColors = new[] { Color.FromArgb(0, 60, 160, 90) }
                };
                g.FillPath(b, bloom);
            }

            using (Pen scan = new Pen(Color.FromArgb(46, 0, 0, 0), 1f))
                for (float y = r.Top + 1; y < r.Bottom; y += 3)
                    g.DrawLine(scan, r.Left, y, r.Right, y);

            // Inner shadow along the top edge
            using (LinearGradientBrush top = new LinearGradientBrush(new RectangleF(r.X, r.Y, r.Width, 12),
                       Color.FromArgb(170, 0, 0, 0), Color.FromArgb(0, 0, 0, 0), 90f))
                g.FillRectangle(top, r.X, r.Y, r.Width, 12);

            g.Restore(state);

            using (Pen rim = new Pen(Color.FromArgb(8, 9, 10), 2f))
                g.DrawPath(rim, shape);

            using (GraphicsPath lip = Theme.Chamfer(RectangleF.Inflate(r, 1.5f, 1.5f), chamfer + 1))
            using (Pen light = new Pen(Color.FromArgb(40, 255, 255, 255), 1f))
                g.DrawPath(light, lip);
        }

        /// <summary>Big chrome letters with a colored glow (VICTORY / DEFEAT, titles).</summary>
        public static void ChromeText(Graphics g, string text, float sizePt, PointF at, Color glow)
        {
            using FontFamily family = new FontFamily(Theme.TitleFamily);
            using GraphicsPath path = new GraphicsPath();
            path.AddString(text, family, (int)FontStyle.Bold, sizePt * 96f / 72f, at, StringFormat.GenericTypographic);

            RectangleF b = path.GetBounds();

            Theme.Glow(g, path, glow, 7, 170);

            using (Pen outline = new Pen(Color.FromArgb(6, 8, 12), 5f) { LineJoin = LineJoin.Round })
                g.DrawPath(outline, path);

            using (Pen ring = new Pen(glow, 1.4f) { LineJoin = LineJoin.Round })
            using (GraphicsPath wide = (GraphicsPath)path.Clone())
            {
                using Pen widen = new Pen(Color.Black, 5f) { LineJoin = LineJoin.Round };
                wide.Widen(widen);
                g.DrawPath(ring, wide);
            }

            using (LinearGradientBrush chrome = new LinearGradientBrush(
                       new RectangleF(b.X, b.Y - 1, b.Width, b.Height + 2), Color.White, Color.Gray, 90f))
            {
                chrome.InterpolationColors = new ColorBlend
                {
                    Colors = new[]
                    {
                        Color.FromArgb(252, 253, 255),
                        Theme.Mix(Color.FromArgb(200, 210, 222), glow, 0.25f),
                        Color.FromArgb(110, 120, 134),
                        Color.FromArgb(38, 42, 52),
                        Theme.Mix(Color.FromArgb(70, 80, 96), glow, 0.35f),
                        Theme.Mix(Color.FromArgb(170, 180, 195), glow, 0.45f)
                    },
                    Positions = new[] { 0f, 0.30f, 0.52f, 0.53f, 0.70f, 1f }
                };
                g.FillPath(chrome, path);
            }

            using (Pen shine = new Pen(Color.FromArgb(110, 255, 255, 255), 0.8f))
                g.DrawPath(shine, path);
        }

        /// <summary>Monitor-style text: a faint bloom around bright letters.</summary>
        public static void GlowText(Graphics g, string text, Font font, Color color, RectangleF r, StringFormat sf, bool bloom = true)
        {
            TextRenderingHint hint = g.TextRenderingHint;
            g.TextRenderingHint = TextRenderingHint.AntiAlias;

            if (bloom)
            {
                using SolidBrush glow = new SolidBrush(Color.FromArgb(46, color));

                foreach ((float dx, float dy) in new[] { (-1f, 0f), (1f, 0f), (0f, -1f), (0f, 1f), (-1.5f, -1f), (1.5f, 1f) })
                    g.DrawString(text, font, glow, new RectangleF(r.X + dx, r.Y + dy, r.Width, r.Height), sf);
            }

            using SolidBrush core = new SolidBrush(color);
            g.DrawString(text, font, core, r, sf);

            g.TextRenderingHint = hint;
        }
    }

    /// <summary>
    /// Short UI sounds (hover, click, switch, PLAY) - generated by
    /// tools/make_skin.py and embedded in the exe. Turned off with UI SOUNDS.
    /// </summary>
    internal static class Sfx
    {
        public static bool Enabled { get; set; } = true;

        private static readonly Dictionary<string, SoundPlayer?> players = new();
        private static DateTime quietUntil;

        public static void Play(string? name)
        {
            if (!Enabled || string.IsNullOrEmpty(name))
                return;

            DateTime now = DateTime.UtcNow;

            // Hover ticks must not cut off a click or the PLAY sound.
            if (name == "hover" && now < quietUntil)
                return;

            try
            {
                SoundPlayer? player = Get(name);

                if (player == null)
                    return;

                player.Play();

                if (name == "play")
                    quietUntil = now.AddMilliseconds(1100);
                else if (name != "hover")
                    quietUntil = now.AddMilliseconds(170);
            }
            catch
            {
                // Sound is not essential.
            }
        }

        private static SoundPlayer? Get(string name)
        {
            if (players.TryGetValue(name, out SoundPlayer? cached))
                return cached;

            SoundPlayer? player = null;

            try
            {
                using Stream? s = Skin.Open("sfx_" + name + ".wav");

                if (s != null)
                {
                    MemoryStream copy = new MemoryStream();
                    s.CopyTo(copy);
                    copy.Position = 0;

                    player = new SoundPlayer(copy);
                    player.Load();
                }
            }
            catch
            {
                player = null;
            }

            players[name] = player;
            return player;
        }
    }
}
